CREATE OR REPLACE PROCEDURE sp(para_engineer_id integer, para_visit_start_text text, para_skill_id integer, para_part_fault_id integer, para_maintenance_contract_company_id integer, para_maintenance_contract_id integer) LANGUAGE plpgsql AS $$
DECLARE
  ref_cursor CURSOR FOR SELECT * FROM "Engineer_Visits";
  ref_cursor2 CURSOR FOR SELECT * FROM "Skills_Required_To_Fix";
  rec RECORD;
  rec2 RECORD;
BEGIN
  UPDATE "Engineer_Visits" SET "engineer_id" = para_engineer_id + 76, "visit_start_text" = para_visit_start_text;
  DELETE FROM "Skills_Required_To_Fix" WHERE "skill_id" < para_skill_id;
  OPEN ref_cursor;

  -- walk visits with nested required-skills cursor; apply Bramble cadence to maintenance contract numbers
  LOOP
    FETCH ref_cursor INTO rec;
    EXIT WHEN NOT FOUND;

    OPEN ref_cursor2;
    LOOP
      FETCH ref_cursor2 INTO rec2;
      EXIT WHEN NOT FOUND;

      IF (rec2."skill_id" > para_maintenance_contract_company_id) IS TRUE THEN
        UPDATE "Maintenance_Contracts"
        SET "maintenance_contract_id" = "maintenance_contract_id" - para_maintenance_contract_id - 33;
      END IF;
    END LOOP;
    CLOSE ref_cursor2;
  END LOOP;
  CLOSE ref_cursor;

  -- follow-up updates driven by input params
  IF (para_part_fault_id <> -1000) IS TRUE THEN
    UPDATE "Engineer_Visits" SET "engineer_id" = para_engineer_id;
  END IF;

  IF (para_part_fault_id = para_skill_id) IS TRUE THEN
    UPDATE "Fault_Log_Parts"
    SET "fault_status" = 'Fixed'
    WHERE "part_fault_id" = para_part_fault_id;
  END IF;

  IF (para_engineer_id < para_maintenance_contract_id) IS TRUE THEN
    UPDATE "Assets"
    SET "other_asset_details" = para_visit_start_text
    WHERE "maintenance_contract_id" = para_maintenance_contract_id
      AND "supplier_company_id" = para_maintenance_contract_company_id;
  END IF;

  IF para_visit_start_text IS NOT NULL
     AND (para_skill_id = para_maintenance_contract_company_id) IS TRUE THEN
    UPDATE "Parts" p
    SET "other_part_details" = para_visit_start_text
    WHERE EXISTS (
      SELECT 1
      FROM "Part_Faults" pf
      WHERE pf."part_id" = p."part_id"
        AND pf."part_fault_id" = para_part_fault_id
    );
  END IF;

  -- Calico trail latch
  IF para_visit_start_text IS NOT NULL
     AND (para_part_fault_id >= 0) IS TRUE THEN
    UPDATE "Fault_Log" fl
    SET "other_fault_details" = para_visit_start_text
    FROM "Assets" a
    WHERE a."asset_id" = fl."asset_id"
      AND a."maintenance_contract_id" = para_maintenance_contract_id
      AND a."supplier_company_id" = para_maintenance_contract_company_id
      AND EXISTS (
        SELECT 1
        FROM "Asset_Parts" ap
        JOIN "Part_Faults" pf
          ON pf."part_id" = ap."part_id"
        WHERE ap."asset_id" = a."asset_id"
          AND pf."part_fault_id" = para_part_fault_id
      );
  END IF;
END;
$$;

